-- Phase 8: customer support, help center, SLA, feedback, and refunds.
ALTER TYPE "RoleCode" ADD VALUE IF NOT EXISTS 'SUPPORT_AGENT';
CREATE TYPE "SupportTicketStatus" AS ENUM ('OPEN','IN_PROGRESS','WAITING_FOR_CUSTOMER','RESOLVED','CLOSED');
CREATE TYPE "SupportPriority" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "RefundStatus" AS ENUM ('REQUESTED','UNDER_REVIEW','APPROVED','REJECTED','PROCESSING','COMPLETED','FAILED');
CREATE TYPE "KnowledgeStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');

CREATE TABLE "SupportCategory" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"isEnabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupportCategory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportCategory_name_key" ON "SupportCategory"("name");CREATE UNIQUE INDEX "SupportCategory_slug_key" ON "SupportCategory"("slug");CREATE INDEX "SupportCategory_isEnabled_sortOrder_idx" ON "SupportCategory"("isEnabled","sortOrder");

CREATE TABLE "SupportTicket" ("id" UUID NOT NULL,"ticketNumber" TEXT NOT NULL,"customerId" UUID NOT NULL,"categoryId" UUID NOT NULL,"assignedAgentId" UUID,"subject" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "SupportTicketStatus" NOT NULL DEFAULT 'OPEN',"priority" "SupportPriority" NOT NULL DEFAULT 'NORMAL',"firstResponseAt" TIMESTAMP(3),"resolvedAt" TIMESTAMP(3),"closedAt" TIMESTAMP(3),"slaResponseDueAt" TIMESTAMP(3),"slaResolutionDueAt" TIMESTAMP(3),"relatedOrderId" UUID,"relatedProjectId" UUID,"relatedEnrollmentId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupportTicket_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportTicket_ticketNumber_key" ON "SupportTicket"("ticketNumber");CREATE INDEX "SupportTicket_customerId_status_createdAt_idx" ON "SupportTicket"("customerId","status","createdAt");CREATE INDEX "SupportTicket_assignedAgentId_status_updatedAt_idx" ON "SupportTicket"("assignedAgentId","status","updatedAt");CREATE INDEX "SupportTicket_categoryId_status_createdAt_idx" ON "SupportTicket"("categoryId","status","createdAt");CREATE INDEX "SupportTicket_status_priority_updatedAt_idx" ON "SupportTicket"("status","priority","updatedAt");

CREATE TABLE "SupportMessage" ("id" UUID NOT NULL,"ticketId" UUID NOT NULL,"senderId" UUID NOT NULL,"body" TEXT NOT NULL,"isInternal" BOOLEAN NOT NULL DEFAULT false,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SupportMessage_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SupportMessage_ticketId_isInternal_createdAt_idx" ON "SupportMessage"("ticketId","isInternal","createdAt");
CREATE TABLE "SupportAttachment" ("id" UUID NOT NULL,"ticketId" UUID NOT NULL,"messageId" UUID,"uploadedById" UUID NOT NULL,"storageKey" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SupportAttachment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SupportAttachment_ticketId_createdAt_idx" ON "SupportAttachment"("ticketId","createdAt");CREATE INDEX "SupportAttachment_messageId_idx" ON "SupportAttachment"("messageId");

CREATE TABLE "SupportAssignment" ("id" UUID NOT NULL,"ticketId" UUID NOT NULL,"agentId" UUID NOT NULL,"assignedById" UUID NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"unassignedAt" TIMESTAMP(3),CONSTRAINT "SupportAssignment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SupportAssignment_ticketId_assignedAt_idx" ON "SupportAssignment"("ticketId","assignedAt");CREATE INDEX "SupportAssignment_agentId_unassignedAt_idx" ON "SupportAssignment"("agentId","unassignedAt");
CREATE TABLE "SupportStatusHistory" ("id" UUID NOT NULL,"ticketId" UUID NOT NULL,"actorId" UUID NOT NULL,"fromStatus" "SupportTicketStatus","toStatus" "SupportTicketStatus" NOT NULL,"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SupportStatusHistory_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SupportStatusHistory_ticketId_createdAt_idx" ON "SupportStatusHistory"("ticketId","createdAt");
CREATE TABLE "SupportSlaPolicy" ("id" UUID NOT NULL,"priority" "SupportPriority" NOT NULL,"firstResponseMinutes" INTEGER NOT NULL,"resolutionMinutes" INTEGER NOT NULL,"timezone" TEXT NOT NULL DEFAULT 'Asia/Yangon',"pauseWhileWaiting" BOOLEAN NOT NULL DEFAULT true,"isEnabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupportSlaPolicy_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportSlaPolicy_priority_key" ON "SupportSlaPolicy"("priority");

CREATE TABLE "KnowledgeCategory" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "KnowledgeCategory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "KnowledgeCategory_name_key" ON "KnowledgeCategory"("name");CREATE UNIQUE INDEX "KnowledgeCategory_slug_key" ON "KnowledgeCategory"("slug");
CREATE TABLE "KnowledgeArticle" ("id" UUID NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"excerpt" TEXT NOT NULL,"content" JSONB NOT NULL,"categoryId" UUID NOT NULL,"authorId" UUID NOT NULL,"status" "KnowledgeStatus" NOT NULL DEFAULT 'DRAFT',"isFeatured" BOOLEAN NOT NULL DEFAULT false,"seoTitle" TEXT,"seoDescription" TEXT,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "KnowledgeArticle_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "KnowledgeArticle_slug_key" ON "KnowledgeArticle"("slug");CREATE INDEX "KnowledgeArticle_status_publishedAt_idx" ON "KnowledgeArticle"("status","publishedAt");CREATE INDEX "KnowledgeArticle_categoryId_status_idx" ON "KnowledgeArticle"("categoryId","status");

CREATE TABLE "RefundRequest" ("id" UUID NOT NULL,"requestNumber" TEXT NOT NULL,"customerId" UUID NOT NULL,"ticketId" UUID,"orderId" UUID,"coursePurchaseId" UUID,"projectInvoiceId" UUID,"requestedAmountMmk" INTEGER NOT NULL,"approvedAmountMmk" INTEGER,"currency" TEXT NOT NULL DEFAULT 'MMK',"reason" TEXT NOT NULL,"evidenceStorageKey" TEXT,"status" "RefundStatus" NOT NULL DEFAULT 'REQUESTED',"reviewerId" UUID,"reviewerNote" TEXT,"refundTransactionReference" TEXT,"reviewedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RefundRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RefundRequest_requestNumber_key" ON "RefundRequest"("requestNumber");CREATE INDEX "RefundRequest_customerId_status_createdAt_idx" ON "RefundRequest"("customerId","status","createdAt");CREATE INDEX "RefundRequest_status_createdAt_idx" ON "RefundRequest"("status","createdAt");
CREATE TABLE "SupportFeedback" ("id" UUID NOT NULL,"ticketId" UUID,"articleId" UUID,"customerId" UUID NOT NULL,"rating" INTEGER NOT NULL,"comment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SupportFeedback_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportFeedback_ticketId_key" ON "SupportFeedback"("ticketId");CREATE INDEX "SupportFeedback_articleId_createdAt_idx" ON "SupportFeedback"("articleId","createdAt");CREATE INDEX "SupportFeedback_customerId_createdAt_idx" ON "SupportFeedback"("customerId","createdAt");
CREATE TABLE "SupportMacro" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"body" TEXT NOT NULL,"isEnabled" BOOLEAN NOT NULL DEFAULT true,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupportMacro_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportMacro_name_key" ON "SupportMacro"("name");

ALTER TABLE "SupportTicket" ADD CONSTRAINT "SupportTicket_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportTicket" ADD CONSTRAINT "SupportTicket_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "SupportCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SupportTicket" ADD CONSTRAINT "SupportTicket_assignedAgentId_fkey" FOREIGN KEY ("assignedAgentId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "SupportTicket" ADD CONSTRAINT "SupportTicket_relatedOrderId_fkey" FOREIGN KEY ("relatedOrderId") REFERENCES "Order"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "SupportTicket" ADD CONSTRAINT "SupportTicket_relatedProjectId_fkey" FOREIGN KEY ("relatedProjectId") REFERENCES "Project"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "SupportTicket" ADD CONSTRAINT "SupportTicket_relatedEnrollmentId_fkey" FOREIGN KEY ("relatedEnrollmentId") REFERENCES "CourseEnrollment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SupportMessage" ADD CONSTRAINT "SupportMessage_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportMessage" ADD CONSTRAINT "SupportMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SupportAttachment" ADD CONSTRAINT "SupportAttachment_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportAttachment" ADD CONSTRAINT "SupportAttachment_messageId_fkey" FOREIGN KEY ("messageId") REFERENCES "SupportMessage"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportAttachment" ADD CONSTRAINT "SupportAttachment_uploadedById_fkey" FOREIGN KEY ("uploadedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SupportAssignment" ADD CONSTRAINT "SupportAssignment_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportAssignment" ADD CONSTRAINT "SupportAssignment_agentId_fkey" FOREIGN KEY ("agentId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SupportAssignment" ADD CONSTRAINT "SupportAssignment_assignedById_fkey" FOREIGN KEY ("assignedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SupportStatusHistory" ADD CONSTRAINT "SupportStatusHistory_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportStatusHistory" ADD CONSTRAINT "SupportStatusHistory_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "KnowledgeArticle" ADD CONSTRAINT "KnowledgeArticle_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "KnowledgeCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "KnowledgeArticle" ADD CONSTRAINT "KnowledgeArticle_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_coursePurchaseId_fkey" FOREIGN KEY ("coursePurchaseId") REFERENCES "CoursePurchase"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_projectInvoiceId_fkey" FOREIGN KEY ("projectInvoiceId") REFERENCES "ProjectInvoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SupportFeedback" ADD CONSTRAINT "SupportFeedback_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportFeedback" ADD CONSTRAINT "SupportFeedback_articleId_fkey" FOREIGN KEY ("articleId") REFERENCES "KnowledgeArticle"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "SupportFeedback" ADD CONSTRAINT "SupportFeedback_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SupportMacro" ADD CONSTRAINT "SupportMacro_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
